mapper.select:
select s.schedule_id as scheduleId, s.schedule_code as scheduleCode, s.course_year as courseYear, s.term_name as termName, s.period_name as periodName, s.time_slot as timeSlot, s.start_time as startTime, s.end_time as endTime, s.grade_name as gradeName, s.subject_name as subjectName, coalesce(nullif(trim(teacher.user_name), ''), nullif(trim(teacher.nick_name), ''), s.teacher_name) as teacherName, s.teacher_id as teacherId, s.class_type as classType, s.course_class_name as courseClassName, c.campus_name as campusName, c.classroom_name as classroomName, ifnull(s.enrolled_count, 0) as enrolledCount, case when e.enrollment_id is null then 0 else 1 end as enrolled from edu_course_schedule s left join sys_user teacher on teacher.user_id = s.teacher_id inner join edu_classroom c on c.classroom_id = s.classroom_id left join edu_enrollment e on e.schedule_id = s.schedule_id and e.parent_id = #{parentId} and e.del_flag = '0' and e.enrollment_status not in ('2', '已取消')
s.del_flag = '0' and s.status = '0' and s.recruit_status = '0' and s.class_mode != '2' and c.status = '0'
and s.grade_name = #{gradeName}
and s.subject_name = #{subjectName}
and s.term_name = #{termName}
order by s.course_year, s.term_name, s.period_name, s.start_time, s.grade_name, s.subject_name, s.schedule_id
